    internal static int BtShownAsLogical(emon.Port.Cells a, int n, emon.Port.Cells want, emon.Port.Cells ar) {
        // 1 when the order the algorithm gives for the code points a[0, n) (read as shown), each mirrored where its
        // level is odd (L4), lists want.
        int k = 0;
        int i = 0;
        int cp = 0;
        int o = 0;
        if (n != emon.Port.CellsLen(want)) {
            return 0;
        }
        emon.Port.CellsDrop(ar, 0);
        while (k < n) {
            emon.Port.CellsPush(ar, emon.Port.CellsAt(a, k));
            k += 1;
        }
        o = Bidi.BdOrderOf(ar, 0, n);
        k = 0;
        while (k < n) {
            i = emon.Port.CellsAt(ar, o + k);
            cp = emon.Port.CellsAt(a, i);
            if (emon.Port.CellsAt(ar, (o - n) + i) == 1) {
                cp = Bidi.BdMirror(cp);
            }
            if (cp != emon.Port.CellsAt(want, k)) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
